87	        assertEquals("SPLIT", currentStatus(parent));
88	        List<String> available = availableKeys();
89	        assertFalse(available.contains(parent));
90	        assertTrue(available.containsAll(childKeys));
91	
92	        // 子批不继承检验或批准记录
93	        for (String childKey : childKeys) {
