113	    @Test
114	    void childBatch_canBeReleasedAndSplitAgain() throws Exception {
115	        String parent = "BK-ML-P-" + unique();
116	        createBatch(parent, List.of("t1"), 201);
117	        releaseBatch(parent, "insp-1");
118	        String child = "BK-ML-C-" + unique();
119	        split(parent, "CK-S1", List.of(new String[]{child, "L1"},
120	                new String[]{"BK-ML-C2-" + unique(), "L2"}), 201);
121	
122	        // 子批重新完成检验与双角色批准后可用
123	        releaseBatch(child, "insp-2");
124	        assertEquals("RELEASED", currentStatus(child));
125	        assertTrue(availableKeys().contains(child));
