174	        createBatch(recalled, List.of("t1"), 201);
175	        releaseBatch(recalled, "insp");
176	        recall(recalled, "u", "质量问题", "CK-RC", 201);
177	        split(recalled, "CK-SRC", twoChildren(), 409);
178	
179	        // 已 SPLIT 的父批不能再次拆分
