188	    @Test
189	    void splitChildKeyConflict_returns409_parentUnchanged_failureDoesNotOccupyKey() throws Exception {
190	        String parent = "BK-SCK-P-" + unique();
191	        createBatch(parent, List.of("t1"), 201);
192	        releaseBatch(parent, "insp");
